select energy_manager.load_cards($cards$[
{"id":"p3-086","paper":3,"topic":"Lighting","kind":"fact","front":"What is Lighting Power Density (LPD), and how is the lighting power allowance calculated?","back":"LPD = installed lighting watts ÷ floor area (W/m²). Allowance = LPD limit × floor area. For example, 14 floors × 1000 m² × 10.8 W/m² = 1,51,200 W.","explain":"ECBC sets maximum LPD values by building type (building area method) or by space (space function method). Lower installed LPD for the same lux means a more efficient design.","flash":false,"source":"BEE 2024 P3 Q24","order":3085},
{"id":"p3-087","paper":3,"topic":"Lighting","kind":"fact","front":"What is ILER, and how is it interpreted?","back":"Installed Load Efficacy Ratio = actual installed load efficacy (lux/W/m²) ÷ target efficacy for that application. ILER of 0.75 or above is satisfactory; 0.51–0.74 needs review; 0.5 or below needs urgent action.","explain":"Installed load efficacy = average maintained lux ÷ (installed W/m²). It is a quick audit indicator of how well the lighting system converts power into useful illuminance.","flash":false,"source":"syllabus","order":3086},
{"id":"p3-088","paper":3,"topic":"Lighting","kind":"problem","front":"A 20 m × 15 m workshop needs 400 lux. Luminaires are 36 W LED, each producing 4000 lumens. Utilisation factor is 0.65 and maintenance factor is 0.8. Find the number of luminaires, the installed LPD, and the installed load efficacy (lux/W/m²).","back":"58 luminaires; LPD ≈ 6.96 W/m²; installed load efficacy ≈ 57.5 lux/W/m².","explain":"The lumen method divides the total lumens needed on the working plane by the effective lumens per luminaire after UF and MF. The LPD check is what ECBC compliance looks at. Installed load efficacy compared with the target gives the ILER.","steps":[{"prompt":"Find the area and total lumens required.","answer":"A = 300 m²; Φ = 400 × 300 = 1,20,000 lm","explain":"Φ = E × A."},{"prompt":"Find the effective lumens per luminaire.","answer":"4000 × 0.65 × 0.8 = 2080 lm","explain":"Lamp lumens × UF × MF."},{"prompt":"Find the number of luminaires.","answer":"1,20,000 / 2080 = 57.7, so 58","explain":"Always round up."},{"prompt":"Find the installed load and LPD.","answer":"58 × 36 = 2088 W; 2088/300 = 6.96 W/m²","explain":"LPD = W/m²."},{"prompt":"Find the installed load efficacy.","answer":"400 / 6.96 ≈ 57.5 lux/W/m²","explain":"Lux ÷ W/m²."}],"flash":false,"source":"BEE 2025 P3 S-1 (similar)","order":3087},
{"id":"p3-089","paper":3,"topic":"DG sets","kind":"fact","front":"How is hourly fuel consumption of a DG set found from kVA, PF and specific fuel consumption?","back":"Fuel (L/h) = kVA × PF × SFC (L/kWh). For example, 1250 kVA × 0.8 × 0.23 = 230 L/h; 1000 kVA × 0.7 × 0.25 = 175 L/h.","explain":"kVA × PF gives kW, and kW × 1 h × L/kWh gives litres. The inverse, kWh per litre (specific energy generation), is the usual DG performance indicator. Typical well-loaded DG sets achieve about 3–4 kWh/L.","flash":true,"source":"BEE 2024 P3 Q18 / BEE 2025 P3 Q46","order":3088},
{"id":"p3-090","paper":3,"topic":"DG sets","kind":"fact","front":"In a DG set, which loss is the largest?","back":"Flue (exhaust) gas loss, followed by cooling water (jacket) loss.","explain":"Only about 30–40% of fuel energy becomes electricity. The hot exhaust (typically 400–500°C) can drive a waste heat boiler or VAM, especially when the DG runs continuously. Stack exit temperature is kept above the acid dew point.","flash":false,"source":"BEE 2025 P3 Q5 / BEE 2024 P3 S1","order":3089},
{"id":"p3-091","paper":3,"topic":"DG sets","kind":"fact","front":"How do altitude and high ambient temperature affect a DG set?","back":"They reduce power output (the set must be derated), because thinner, hotter air holds less oxygen mass for combustion.","explain":"Manufacturers give derating factors for altitude, ambient temperature and humidity. Choose the DG capacity using site-derated output, not nameplate rating.","flash":false,"source":"BEE 2024 P3 Q14","order":3090},
{"id":"p3-092","paper":3,"topic":"DG sets","kind":"fact","front":"Name good operating practices for DG set energy efficiency.","back":"Load the set near its optimum (typically above about 60–70%); avoid low-load running; operate parallel sets to share load sensibly; keep phase loads balanced; maintain PF near the rated 0.8 or above; keep intake air cool and clean; recover exhaust heat; monitor kWh per litre.","explain":"Alternator losses rise at low PF because higher current is drawn for the same kW, so alternator losses are not independent of PF. DG sets are not designed to tolerate large phase unbalance (such as 25%); unbalance causes alternator overheating.","flash":false,"source":"BEE 2025 P3 L-2","order":3091},
{"id":"p3-093","paper":3,"topic":"DG sets","kind":"problem","front":"A 500 kVA DG set (rated PF 0.8) supplies an average of 320 kW for 1 hour on test and consumes 95 litres of diesel (density 0.85 kg/L, GCV 10,800 kcal/kg). Find the percentage loading, specific energy generation (kWh/L), overall thermal efficiency, and the fuel cost per kWh at Rs 90/L.","back":"Loading 80%; ≈ 3.37 kWh/L; efficiency ≈ 31.6%; ≈ Rs 26.7/kWh.","explain":"DG performance is tracked by kWh per litre (or its inverse, SFC in L/kWh). Overall efficiency = electrical output (kWh × 860 kcal/kWh) ÷ fuel heat input. A falling kWh/L trend signals poor loading, injector or turbocharger problems.","steps":[{"prompt":"Find the percentage loading.","answer":"Rated kW = 500 × 0.8 = 400 kW; loading = 320/400 = 80%","explain":"Loading on kW rating."},{"prompt":"Find the specific energy generation.","answer":"320 kWh / 95 L = 3.37 kWh/L (SFC = 0.297 L/kWh)","explain":"kWh per litre."},{"prompt":"Find the fuel heat input.","answer":"95 × 0.85 = 80.75 kg; × 10,800 = 8,72,100 kcal","explain":"Mass × GCV."},{"prompt":"Find the thermal efficiency.","answer":"320 × 860 / 8,72,100 = 31.6%","explain":"1 kWh = 860 kcal."},{"prompt":"Find the fuel cost per kWh.","answer":"90 / 3.37 ≈ Rs 26.7/kWh","explain":"Fuel price ÷ kWh/L."}],"flash":false,"source":"BEE 2025 P3 L-5 / Q46 (similar)","order":3092},
{"id":"p3-094","paper":3,"topic":"Energy-efficient technologies","kind":"fact","front":"Why does a VFD save the most energy on centrifugal pumps and fans?","back":"These are variable-torque loads whose power varies with speed³. Matching speed to demand, instead of throttling, captures cube-law savings.","explain":"Constant-torque loads (conveyors, positive-displacement pumps, screw compressors) save roughly in proportion to speed, so savings are smaller but still worthwhile where output varies. VFDs also give soft starting. The trade-offs are VFD losses (about 2–4%) and harmonic generation.","flash":false,"source":"syllabus","order":3093},
{"id":"p3-b01-001","paper":3,"topic":"Power Supply System","kind":"fact","front":"Name the five components of an electric power supply system.","back":"Generating units, high-voltage transmission lines, distribution lines, substations, and energy control centres.","explain":"Generators produce electricity, transmission lines carry it over long distances, distribution lines deliver it to consumers, and substations connect the pieces. Energy control centres coordinate the operation of all components.","flash":false,"source":"BEE Book 3 Ch 01 p21","order":3094},
{"id":"p3-b01-002","paper":3,"topic":"Power Generation","kind":"fact","front":"What is the heat rate of a power plant, and in what units is it expressed?","back":"The heat input (in kcal or kJ) needed to generate one kWh of electrical output.","explain":"One kWh is equivalent to 860 kcal or 3600 kJ of thermal energy. Heat rate is inversely proportional to efficiency, so a coal plant at 28-35% efficiency has a heat rate of roughly 2450-3070 kcal/kWh.","flash":false,"source":"BEE Book 3 Ch 01 p22","order":3095},
{"id":"p3-b01-003","paper":3,"topic":"Transmission & Distribution","kind":"fact","front":"What are the sub-transmission and distribution voltage levels named in this chapter?","back":"Sub-transmission: 132, 110, 66 or 33 kV. Distribution (last link to the consumer): 11, 6.6 or 3.3 kV.","explain":"Sub-stations containing step-down transformers reduce the voltage at each link. Consumers connect directly at distribution voltage or through transformers, depending on the level of service.","flash":false,"source":"BEE Book 3 Ch 01 p22","order":3096},
{"id":"p3-b01-004","paper":3,"topic":"Transmission & Distribution","kind":"problem","front":"If the distribution voltage is raised from 11 kV to 33 kV for the same power and the same line, by what factor does the line power loss fall?","back":"To 1/9 of the original (nine times lower).","explain":"Current falls in proportion to voltage for the same power, and line loss depends on the current squared, so the voltage ratio enters the loss calculation squared.","flash":false,"source":"BEE Book 3 Ch 01 p23","steps":[{"prompt":"Find the voltage ratio.","answer":"33 kV / 11 kV = 3.","explain":"The ratio sets how much the current and voltage drop change."},{"prompt":"How does the current change for the same power?","answer":"Current is inversely proportional to voltage, so it falls to 1/3.","explain":"For a fixed power, current is proportional to 1/V."},{"prompt":"How does the voltage drop change?","answer":"Voltage drop falls by a factor of 1/3.","explain":"Drop is proportional to the line current for the same resistance and length."},{"prompt":"How does the line loss change?","answer":"Loss is proportional to I2R, so the factor is (1/3)2 = 1/9 of the original.","explain":"Squaring the current reduction gives the nine-fold saving."}],"order":3097},
{"id":"p3-b01-005","paper":3,"topic":"Power Supply System","kind":"fact","front":"Why must electricity be generated only as and when it is needed?","back":"Electricity cannot be stored in the system in bulk, so generation must match demand at every instant.","explain":"This is why load management matters: peaks force utilities to add or run costly capacity, so reducing peak demand benefits both the utility and the consumer.","flash":true,"source":"BEE Book 3 Ch 01 p23","order":3098},
{"id":"p3-b01-006","paper":3,"topic":"Distribution Losses","kind":"fact","front":"What is the standard technical T&D loss in India, and why do state figures run higher?","back":"Standard technical losses are about 17% (efficiency 83%). State T&D losses range from 17% to 50% because unmetered supply and pilferage are also counted.","explain":"Only part of the gap is technical; the rest is commercial loss from theft, unmetered use and billing failures. The 83% efficiency is the benchmark against which state figures are compared.","flash":true,"source":"BEE Book 3 Ch 01 p25","order":3099},
{"id":"p3-b01-007","paper":3,"topic":"T&D Efficiency","kind":"problem","front":"Find the overall T&D cascade efficiency from plant output to end use, using stage efficiencies of 99.5%, 99%, 97.5%, 96%, 99.5% and 95%.","back":"About 87% (0.995 x 0.99 x 0.975 x 0.96 x 0.995 x 0.95 = 0.872).","explain":"Energy passes through each stage in turn, so the stage efficiencies multiply to give the cascade efficiency from generation to the user.","flash":false,"source":"BEE Book 3 Ch 01 p25","steps":[{"prompt":"Multiply the step-up and EHV stage efficiencies.","answer":"0.995 x 0.99 = 0.985.","explain":"Step-up station and EHV transmission are the first two stages."},{"prompt":"Multiply by the HV transmission stage.","answer":"0.985 x 0.975 = 0.960.","explain":"Each stage multiplies the energy that passes on to the next."},{"prompt":"Multiply by the sub-transmission stage.","answer":"0.960 x 0.96 = 0.922.","explain":"Sub-transmission at 66/132 kV is the fourth stage."},{"prompt":"Multiply by the distribution step-down stage.","answer":"0.922 x 0.995 = 0.917.","explain":"Step-down to 11/33 kV is the fifth stage."},{"prompt":"Multiply by the primary distribution stage and express as a percentage.","answer":"0.917 x 0.95 = 0.872, i.e. about 87%.","explain":"This matches the chapter's cascade efficiency result."}],"order":3100},
{"id":"p3-b01-008","paper":3,"topic":"T&D Efficiency","kind":"problem","front":"Plant-level stage efficiencies are: T&D 83%, in-plant distribution including transformer 95%, motor 90% and mechanical (drive, pump, valve) 70%. What is the overall end-use efficiency, and how many units must be generated to deliver one unit saved at the end use?","back":"About 50%. One unit saved at the end user equals two units generated (1 / 0.5).","explain":"Savings at the point of use are multiplied back through the whole chain, which is why end-use savings are so valuable.","flash":false,"source":"BEE Book 3 Ch 01 p26","steps":[{"prompt":"Multiply the T&D and in-plant distribution efficiencies.","answer":"0.83 x 0.95 = 0.7885.","explain":"Power from the grid passes through the T&D network and the plant distribution system."},{"prompt":"Multiply by the motor efficiency.","answer":"0.7885 x 0.90 = 0.7097.","explain":"Motor efficiency is the next link in the chain."},{"prompt":"Multiply by the mechanical efficiency.","answer":"0.7097 x 0.70 = 0.4968, i.e. about 50%.","explain":"Coupling, drive train, pump and throttling losses make up the last stage."},{"prompt":"Find the units generated per unit saved at the end use.","answer":"1 / 0.50 = 2 units.","explain":"The chapter's rule: one unit saved at the end user equals two units generated at the plant."}],"order":3101},
{"id":"p3-b01-009","paper":3,"topic":"Maximum Demand","kind":"problem","front":"In one 30-minute recording interval a load draws 2500 kVA for 4 min, 3600 kVA for 12 min, 4100 kVA for 6 min and 3800 kVA for 8 min. What maximum demand does the meter record?","back":"About 3606.7 kVA (the time-integrated average over the 30-minute interval).","explain":"The meter records the average demand over the interval, not the instantaneous peak. The 4100 kVA peak lasts only 6 minutes and is averaged down.","flash":false,"source":"BEE Book 3 Ch 01 p27","steps":[{"prompt":"Compute the kVA-minutes for each segment.","answer":"2500 x 4 = 10,000; 3600 x 12 = 43,200; 4100 x 6 = 24,600; 3800 x 8 = 30,400.","explain":"Demand multiplied by time gives the energy drawn in that segment."},{"prompt":"Sum the kVA-minutes.","answer":"10,000 + 43,200 + 24,600 + 30,400 = 108,200 kVA-min.","explain":"This is the total energy over the interval."},{"prompt":"Check that the durations add up to the recording interval.","answer":"4 + 12 + 6 + 8 = 30 min, matching the 30-minute interval.","explain":"Confirms no time is missed or double counted."},{"prompt":"Divide by the interval length.","answer":"108,200 / 30 = 3606.7 kVA.","explain":"The interval average is the maximum demand recorded for that cycle."}],"order":3102},
{"id":"p3-b01-010","paper":3,"topic":"Electricity Billing","kind":"fact","front":"What minimum quantities does a utility's trivector meter record for billing?","back":"Maximum demand (kVA) in the month, active energy (kWh), reactive energy (kVArh) and apparent energy (kVAh) for the billing cycle.","explain":"Maximum demand is measured over preset intervals (e.g. 30 minutes) and reset at the end of every billing cycle. The highest interval value is billed even if it lasts only one interval.","flash":false,"source":"BEE Book 3 Ch 01 p27","order":3103},
{"id":"p3-b01-011","paper":3,"topic":"Electricity Billing","kind":"fact","front":"On what basis may a utility bill maximum demand when it uses minimum billing demand?","back":"On the higher of actual recorded demand and a minimum of 75% to 100% of contract demand.","explain":"Under this clause a plant can pay for demand it did not draw. Compare contract demand with recorded demand before deciding whether to surrender any of it.","flash":true,"source":"BEE Book 3 Ch 01 p28","order":3104},
{"id":"p3-b01-012","paper":3,"topic":"Power Factor","kind":"fact","front":"Define power factor in terms of kW and kVA.","back":"PF = kW / kVA = cos phi. It is always less than or equal to 1.","explain":"kW is the active power doing work, kVAr is the reactive power that builds magnetic fields, and kVA is their vector sum, which is the load the distribution system actually carries. Inductive industrial loads often run at PF 0.2 to 0.9.","flash":false,"source":"BEE Book 3 Ch 01 p30","order":3105},
{"id":"p3-b01-013","paper":3,"topic":"Power Factor","kind":"fact","front":"Name four benefits of improving power factor by adding capacitors.","back":"Lower total current and reactive component from the source; lower I2R losses; higher voltage at the load end; kVA loading relief on generators, transformers and lines.","explain":"The freed capacity lets the same transformer or feeder carry more load. Lower kVA also reduces maximum demand charges and avoids PF penalties.","flash":false,"source":"BEE Book 3 Ch 01 p31","order":3106},
{"id":"p3-b01-014","paper":3,"topic":"Power Factor","kind":"problem","front":"A 1500 kVA transformer supplies a plant drawing 1160 kVA at PF 0.70. If 410 kVAr of capacitors is added, what are the new kVA, PF and transformer loading?","back":"About 913 kVA, PF 0.89, and about 60% loading (913 / 1500).","explain":"Capacitors cut the reactive part of the load, so kVA falls while kW stays the same.","flash":false,"source":"BEE Book 3 Ch 01 p31","steps":[{"prompt":"Find the active power.","answer":"812 kW (1160 x 0.70).","explain":"kW = kVA x PF. Adding capacitors does not change kW."},{"prompt":"Find the original reactive power.","answer":"sqrt(1160^2 - 812^2) = about 828 kVAr.","explain":"kVA^2 = kW^2 + kVAr^2."},{"prompt":"Subtract the capacitor kVAr.","answer":"828 - 410 = 418 kVAr.","explain":"Capacitors supply part of the reactive power locally."},{"prompt":"Find the new kVA.","answer":"sqrt(812^2 + 418^2) = about 913 kVA.","explain":"The reduced kVA is the new load on the transformer."},{"prompt":"Find the new PF and transformer loading.","answer":"PF = 812 / 913 = 0.89; loading = 913 / 1500 = about 61% (chapter says about 60%).","explain":"The transformer gains spare capacity for future loads."}],"order":3107},
{"id":"p3-b01-015","paper":3,"topic":"Automatic PF Control","kind":"fact","front":"Why are automatic power factor controllers used where loads fluctuate, instead of fixed capacitor banks?","back":"Fixed banks cannot hold PF near unity when the load fluctuates. At light load the PF can go leading, raising motor-terminal voltage and maximum demand, so the controller switches banks on and off to track the set PF.","explain":"The controller displays PF at the point of supply, compares it with the target, and switches capacitor steps through relay outputs. Typically 6 to 14 relays are provided.","flash":false,"source":"BEE Book 3 Ch 01 p32","order":3108},
{"id":"p3-b01-016","paper":3,"topic":"Capacitors","kind":"problem","front":"A plant's average load is 627 kW at PF 0.72. How many kVAr of capacitors are needed to raise the PF to 0.95?","back":"About 398 kVAr (install a 400 kVAr bank).","explain":"kVAr = kW x (tan phi1 - tan phi2). The chapter's multiplier table gives the same answer (0.635 for 0.72 to 0.95).","flash":false,"source":"BEE Book 3 Ch 01 p33","steps":[{"prompt":"Find tan phi1 for PF 0.72.","answer":"cos phi1 = 0.72, so tan phi1 = 0.964 (chapter value).","explain":"Use the inverse cosine to get the angle, then its tangent."},{"prompt":"Find tan phi2 for PF 0.95.","answer":"cos phi2 = 0.95, so tan phi2 = 0.329.","explain":"Same method for the target power factor."},{"prompt":"Find the difference of the tangents.","answer":"0.964 - 0.329 = 0.635.","explain":"This is the multiplier per kW of load."},{"prompt":"Multiply by the average kW.","answer":"627 x 0.635 = about 398 kVAr.","explain":"This is the reactive power the capacitors must supply."},{"prompt":"Choose the standard size.","answer":"Install 400 kVAr.","explain":"Round up to the nearest available capacitor rating."}],"order":3109},
{"id":"p3-b01-017","paper":3,"topic":"Capacitors","kind":"fact","front":"Where should power factor capacitors be placed to give the maximum benefit?","back":"As close as possible to the load, ideally at each piece of equipment, so that the kVAr is confined to the smallest possible segment and current and losses fall.","explain":"Losses are proportional to the square of the current, so capacitors near the load cut losses across the system. Motor voltage and performance also improve.","flash":false,"source":"BEE Book 3 Ch 01 p35","order":3110},
{"id":"p3-b01-018","paper":3,"topic":"Capacitors","kind":"fact","front":"What is the largest capacitor rating that should be connected at a motor's terminals?","back":"Not greater than the motor's no-load magnetising kVAr. Larger units can cause damaging over-voltage or transient torques.","explain":"Motor makers usually specify maximum capacitor ratings for each motor. Individual motor correction is generally economic from about 10 HP upward.","flash":true,"source":"BEE Book 3 Ch 01 p36","order":3111},
{"id":"p3-b01-019","paper":3,"topic":"Capacitors","kind":"fact","front":"What is the energy-efficiency limitation of placing PF capacitors only at the main service or receiving substation?","back":"It reduces losses only on the utility side. It does not reduce losses inside the plant network and does not improve the load capability of the distribution system.","explain":"Tail-end correction in the plant's own network also cuts losses there and directly reduces consumption. Main-service capacitors are cheapest to install but usually need switching to control the capacitance.","flash":true,"source":"BEE Book 3 Ch 01 p36","order":3112},
{"id":"p3-b01-020","paper":3,"topic":"Capacitors","kind":"fact","front":"Are single-phase motor-starting capacitors or lighting voltage-boost capacitors suitable for power factor correction?","back":"No. They are not power factor capacitor units and cannot withstand power-system conditions.","explain":"Check PF capacitors by their charging current, since nameplates can mislead and some capacitor boxes contain no capacitor elements.","flash":false,"source":"BEE Book 3 Ch 01 p37","order":3113},
{"id":"p3-b01-021","paper":3,"topic":"Transformers","kind":"fact","front":"How is the secondary voltage of a transformer related to its turns ratio?","back":"Secondary voltage = primary voltage x turns ratio (secondary turns / primary turns). Primary ampere-turns equal secondary ampere-turns.","explain":"Stepping voltage up lowers the current for the same power, which is why power is generated at low voltage, transmitted at high voltage and suffers less line loss.","flash":false,"source":"BEE Book 3 Ch 01 p38","order":3114},
{"id":"p3-b01-022","paper":3,"topic":"Transformers","kind":"fact","front":"How are transformers classified by voltage in this chapter?","back":"Power transformers for transmission (400, 220, 110, 66 and 33 kV). Distribution transformers for distribution networks (11, 6.6, 3.3 kV, 440 V and 230 V).","explain":"The OCR text reads 200 kV for the transmission level; 220 kV is used here, matching the chapter's transmission voltages. Distribution transformers connect the network to end users.","flash":false,"source":"BEE Book 3 Ch 01 p38","order":3115},
{"id":"p3-b01-023","paper":3,"topic":"Transformers","kind":"fact","front":"What is diversity factor, and what is its range?","back":"Diversity factor = overall maximum demand of the plant / sum of the individual maximum demands of its loads. It is always less than one.","explain":"Transformer kVA rating = connected load x diversity factor for the industry. The factor depends on individual loads, load factor and future expansion plans.","flash":false,"source":"BEE Book 3 Ch 01 p38","order":3116},
{"id":"p3-b01-024","paper":3,"topic":"Transformers","kind":"fact","front":"What must two transformers have in common before they are operated in parallel?","back":"Same phase-angle displacement, same voltage ratio, same percentage impedance, same polarity and same phase sequence.","explain":"Technically identical units with matching impedance minimise circulating current. Parallel operation also lets the load be shared as it fluctuates, keeping transformers near their maximum efficiency range.","flash":false,"source":"BEE Book 3 Ch 01 p41","order":3117},
{"id":"p3-b01-025","paper":3,"topic":"Standards & Labelling","kind":"fact","front":"From what date are distribution transformers under the BEE Standards & Labelling programme, and what does 1 star represent?","back":"Mandatory from 7 January 2010. 1 star is the base case, equal to the IS 1180 (Part 1) loss levels; 5 star is the lowest-loss segment.","explain":"Labelling is based on total losses at 50% and 100% loading. A higher star rating means lower losses.","flash":true,"source":"BEE Book 3 Ch 01 p42","order":3118},
{"id":"p3-b01-026","paper":3,"topic":"Distribution Losses","kind":"fact","front":"List four factors that increase technical losses in a distribution system.","back":"Lengthy radial LT and 11 kV lines in rural areas; undersized conductors for load growth; distribution transformers not located at the load centre; low power factor.","explain":"Each raises I2R loss: long lines add resistance, undersized conductors run hot, distant transformers force long secondary runs with voltage drop, and low PF draws more current.","flash":false,"source":"BEE Book 3 Ch 01 p44","order":3119},
{"id":"p3-b01-027","paper":3,"topic":"Distribution Losses","kind":"fact","front":"What are the normative total technical loss limits in Indian transmission and distribution networks?","back":"Total 7.0% minimum to 15.5% maximum. Components: step-up and EHV 0.5-1.0%; transmission to intermediate voltage and step-down to sub-transmission 1.5-3.0%; sub-transmission to distribution 2.0-4.5%; distribution lines and service connections 3.0-7.0%.","explain":"The component minimums add up to 7.0 and the maximums add up to 15.5, which gives the total range in the chapter's Table 1.6.","flash":false,"source":"BEE Book 3 Ch 01 p44","order":3120},
{"id":"p3-b01-028","paper":3,"topic":"Distribution Losses","kind":"problem","front":"A 300 kW load on an 11 kV line has a line loss of 27.2 kW at PF 0.70. What is the line loss at unity PF for the same load?","back":"About 13.4 kW, roughly half the original (ratio 0.49).","explain":"At the same kW, a lower PF means higher kVA and current. Loss depends on current squared, so loss scales with (PF before / PF after) squared.","flash":false,"source":"BEE Book 3 Ch 01 p45","steps":[{"prompt":"Find the kVA at PF 0.70.","answer":"300 / 0.70 = about 428 kVA.","explain":"For a given voltage, current is proportional to kVA."},{"prompt":"Find the current ratio against unity PF.","answer":"428 / 300 = 1.43.","explain":"At unity PF the kVA equals the kW, so the current is lower in the same ratio."},{"prompt":"Find the loss ratio.","answer":"(1.43)^2 = about 2.04, so loss at PF 0.70 is about twice the loss at unity PF.","explain":"Loss is proportional to I^2."},{"prompt":"Find the unity PF loss.","answer":"27.2 / 2.04 = about 13.3 kW (chapter value 13.4 kW). Equivalently 27.2 x 0.70^2.","explain":"The small difference is rounding in the chapter's table."}],"order":3121},
{"id":"p3-b01-029","paper":3,"topic":"Commercial Losses","kind":"fact","front":"What is collection efficiency, and how does it feed into AT&C loss?","back":"Collection efficiency = amount collected / total amount billed x 100%. AT&C loss = [1 - (billing efficiency x collection efficiency)] x 100.","explain":"AT&C combines technical losses (captured by billing efficiency) and commercial losses such as theft, meter tampering and poor collection into one utility-level figure.","flash":false,"source":"BEE Book 3 Ch 01 p46","order":3122},
{"id":"p3-b01-030","paper":3,"topic":"Commercial Losses","kind":"problem","front":"A utility has billing efficiency of 70%, amount billed Rs 400 lakh, gross amount collected Rs 410 lakh and arrears collected Rs 40 lakh. Find the collection efficiency and the AT&C loss.","back":"Collection efficiency about 93% (92.5%); AT&C loss about 35%.","explain":"Arrears relate to earlier billing periods, so they are removed before comparing collections with current billing. AT&C combines billing and collection efficiency.","flash":false,"source":"BEE Book 3 Ch 01 p47","steps":[{"prompt":"Find the amount collected without arrears.","answer":"Ac = AG - Ar = 410 - 40 = Rs 370 lakh.","explain":"Only current-period collections are set against current billing."},{"prompt":"Find the collection efficiency.","answer":"CE = Ac / Ab x 100 = 370 / 400 = 92.5% (about 93%).","explain":"Ab is the amount billed."},{"prompt":"Find the AT&C loss.","answer":"AT&C = [1 - (0.70 x 0.925)] x 100 = 35.25%.","explain":"Billing efficiency is given as 70%."},{"prompt":"Round the result.","answer":"About 35%, matching the chapter's Table 1.7.","explain":"Using 93% gives 34.9%, which also rounds to 35%."}],"order":3123},
{"id":"p3-b01-031","paper":3,"topic":"Demand Side Management","kind":"fact","front":"What is Demand Side Management (DSM)?","back":"Actions taken on the customer's side of the meter to change the amount (kWh) or timing (kVA) of energy consumption, so as to avoid or postpone building new generating plants.","explain":"DSM aims to maximise end-use efficiency. It is often more cost-effective and resource-efficient than adding supply capacity.","flash":false,"source":"BEE Book 3 Ch 01 p47","order":3124},
{"id":"p3-b01-032","paper":3,"topic":"Demand Side Management","kind":"fact","front":"List the five steps of the DSM implementation methodology.","back":"1. Load research; 2. Define load-shape objectives; 3. Assess programme implementation strategies; 4. Implementation; 5. Monitoring and evaluation.","explain":"Load research profiles the customer base, tariff and hourly load to find the peak-load contributors. Evaluation compares results with the utility's goal using a benefit-cost analysis.","flash":false,"source":"BEE Book 3 Ch 01 p48","order":3125}
]$cards$::jsonb);
